INSERT INTO third_party_source (name, publisher, url, tier, form, has_numbers, access, note, updated_at) VALUES ('迷惑情報データベース','トビラシステムズ','https://tobila.com/','A','B2Bフィード（警察提供番号＋利用者報告＋独自調査）',1,'licensed','事業者番号データ約600万件（iタウンページ含む）。Web表示には商用ライセンスが必要。本プロジェクトは無料リソースのみを使う方針のため未契約','2026-10-22');
