INSERT INTO third_party_source (name, publisher, url, tier, form, has_numbers, access, note, updated_at) VALUES ('注意喚起・悪質通販サイト情報','消費者庁／国民生活センター','https://www.kokusen.go.jp/','C','PDF（叙述）／サイトURLリスト',0,'public','電話番号単位のデータではないため third_party_flag には投入しない','2026-10-22');
